function checkEmployeeScope({ employee, authUser, role }) {
  if (hasRole(role, [ROLES.SUPER_ADMIN])) return null;

  if (
    !authUser?.companyId ||
    String(employee.companyId || "") !== String(authUser.companyId || "")
