  let nearestDistance = Infinity;

  for (const area of areas) {
    const dist = getDistance(
      latitude,
      longitude,
      area.latitude,
      area.longitude,
    );

    if (dist < nearestDistance) {
      nearestDistance = dist;
      nearestArea = area;
    }

    if (dist <= (area.radius || 100)) {
      return {
        matchedArea: area,
        nearestArea: area,
        nearestDistance: dist,
      };
    }
  }

  return {
    matchedArea: null,
    nearestArea,
    nearestDistance,
  };
}

